totals = {}
counts = {}
with open('scores.txt', encoding='utf-8') as f:
    for line in f:
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        name, subject, score = line.split()
        totals[name] = totals.get(name, 0) + int(score)
        counts[name] = counts.get(name, 0) + 1
for name in sorted(totals, key=lambda name: (-totals[name], name)):
    print(name, totals[name], counts[name])

