def state_after(start, step, k):
    seen = {}
    x, t = start, 0
    while t < k:
        if x in seen:
            cycle = t - seen[x]
            for _ in range((k - t) % cycle):
                x = step(x)
            return x
        seen[x] = t
        x = step(x)
        t += 1
    return x

